  const roundCard=gamesState.gamesCompleted?`<article class="games-card games-round-card games-final-card"><p class="eyebrow">Final Podium</p><h2>Official Final Standings</h2>${finalStandingsHtml()}</article>`:`<article class="games-card games-round-card"><p class="eyebrow">Current Round</p><div class="games-round-title"><h2>${esc(week?.name||"Coming Soon")}</h2><span class="games-live-chip">${week&&!isWeekPublished(week.id)?"IN PROGRESS":"PUBLISHED"}</span></div><div class="games-round-kpi"><b>${challengeCount}</b><span>scheduled challenges</span></div>${week?`<p class="games-muted">${fmtDate(week.startDate)} → ${fmtDate(week.endDate)}</p>`:""}${gamesState.myTeam?`<div class="games-myteam-mini"><span>Your Team</span><strong>${esc(gamesState.myTeam.name)}</strong></div>`:""}<button class="games-btn secondary" data-jump-tab="week">Open This Week</button></article>`;
